const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const activeAssets=()=>assets.filter(a=>!['Retired','Sold','Decommissioned'].includes(a.status));
const serviceConfig=require('../service-types');
const serviceTypes=[...Object.values(serviceConfig.groups).flat().map(x=>x.value),'Defect Repair'];
function validType(asset,type){return serviceConfig.valid(asset,type)}
function listOptions(asset){const choices=serviceConfig.options(asset).slice();for(const list of parts.read().lists.filter(x=>x.assetId===String(asset?.id))){if(!choices.some(x=>x.value===list.serviceType))choices.push({value:list.serviceType,label:list.serviceType+' (existing parts list)'});}return choices}
function validListType(asset,type){return !!asset&&listOptions(asset).some(x=>x.value===type)}
router.get('/api/service-types',(req,res)=>{res.set('Cache-Control','no-store');res.json(Object.fromEntries(assets.map(a=>[String(a.id),{category:serviceConfig.category(a),options:req.query.lists==='1'?listOptions(a):serviceConfig.options(a)}])))});
const vehicleLabel=a=>[String(a.plantId||a.rego||'').trim(),String(a.name||[a.make,a.model].filter(Boolean).join(' ')||a.type||'Unnamed asset').trim()].filter(Boolean).join(' | ');
const today=()=>new Date().toISOString().slice(0,10);
const daysBetween=(a,b)=>Math.ceil((new Date(b+'T00:00:00')-new Date(a+'T00:00:00'))/86400000);
function state(r){if(r.status==='COMPLETED')return{label:'Completed',cls:'ok'};if(r.status==='CANCELLED')return{label:'Cancelled',cls:'bad'};const d=daysBetween(today(),r.requestedDate);if(d<0)return{label:'Overdue',cls:'bad'};if(d<=7)return{label:'Due ≤ 7 Days',cls:'due'};if(d<=30)return{label:'Due ≤ 30 Days',cls:'daily'};return{label:'Scheduled',cls:'ok'}}
function requestedDateISO(value){
  const text=String(value||'').trim();
  const dotted=/^([0-9]{2})[./]([0-9]{2})[./]([0-9]{4})$/.exec(text);
  const iso=dotted?dotted[3]+'-'+dotted[2]+'-'+dotted[1]:text;
  if(!/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(iso)||iso.slice(0,4)==='0000')throw new Error('Enter Requested Date as dd/mm/yyyy');
  const date=new Date(iso+'T00:00:00Z');
  if(!Number.isFinite(date.getTime())||date.toISOString().slice(0,10)!==iso)throw new Error('Enter a valid Requested Date as dd/mm/yyyy');
  return iso;
}
function displayRequestedDate(value){const parts=String(value||'').split('-');return parts.length===3?parts[2]+'/'+parts[1]+'/'+parts[0]:String(value||'—')}
function partsPreview(assetId,serviceType){
 const lines=serviceType==='Certificate of Inspection'?[]:parts.snapshot(assetId,serviceType);
 const revision=require('crypto').createHash('sha256').update(JSON.stringify(lines.map(({id,...line})=>line))).digest('hex');
 return {parts:lines,revision};
}
router.get('/api/service-parts/preview',(req,res)=>{
 if(!validType(assets.find(a=>String(a.id)===String(req.query.asset)),req.query.type))return res.status(400).json({error:'Select a valid asset and service type'});
 res.set('Cache-Control','no-store');res.json(partsPreview(req.query.asset,req.query.type));
});
function createBooking(b){
  for(const f of ['vehicleId','serviceType','requestedDate'])if(!b[f])throw new Error(`${f} is required`);
  const asset=assets.find(a=>String(a.id)===String(b.vehicleId));
  if(!asset)throw new Error('Selected vehicle was not found');
  if(!validType(asset,String(b.serviceType)))throw new Error('Select a service type that matches this asset class');
  const defect=defectLink.validate(b.defectId,asset.id);
  const choice=b.partsRequired;
  const required=String(b.serviceType)!=='Certificate of Inspection'&&(choice===undefined?true:[true,'true','1','on',1].includes(choice));
  const preview=required?partsPreview(asset.id,String(b.serviceType)):{parts:[],revision:''};
  if(required&&choice!==undefined&&preview.parts.length&&b.partsConfirmation!==preview.revision)throw new Error('Review and confirm the saved parts. If the list has changed, refresh parts and confirm again.');
  const confirmed=required&&preview.parts.length>0&&b.partsConfirmation===preview.revision;
  const now=new Date().toISOString();
  const row={id:'SVC-'+Date.now().toString(36).toUpperCase()+'-'+Math.random().toString(36).slice(2,6).toUpperCase(),assetId:asset.id,rego:asset.rego,assetName:asset.name,assetType:asset.type,serviceType:String(b.serviceType),requestedDate:requestedDateISO(b.requestedDate),serviceCentre:String(b.serviceCentre||'').trim(),notes:String(b.notes||'').trim(),reminderDays:Number(b.reminderDays)||14,status:'SCHEDULED',createdAt:now,updatedAt:now,completedDate:null,completedReading:null,completionNotes:'',cancelledAt:null,partsRequired:required,partsConfirmedAt:confirmed?now:null,partsAllocationStatus:!required?'not required':preview.parts.length?(confirmed?'confirmed':'pending confirmation'):'awaiting allocation',parts:preview.parts};
  if(defect){row.defectId=defect.id;row.defectNotice={id:defect.id,defect:defect.defect,description:defect.description||'',photo:defect.photo||'',prestartId:defect.prestartId,reportedAt:defect.reportedAt,priority:defect.priority};row.notes=[row.notes,'Defect reference: '+defect.id+' · '+defect.defect,defect.description||''].filter(Boolean).join('\n');}
  services.save(row);defectLink.attach(row,defect);return row;
}

router.post('/service/schedule',(req,res)=>{try{createBooking(req.body||{});res.redirect('/service?scheduled=1')}catch(e){res.status(400).send(page('service','Service Schedule',`<div class="panel" style="padding:24px"><h2>Unable to schedule service</h2><p>${esc(e.message)}</p><a class="primary" href="/service">Return to Service Schedule</a></div>`))}});
router.post('/api/services',(req,res)=>{try{res.status(201).json(createBooking(req.body||{}))}catch(e){res.status(400).json({error:e.message})}});
router.get('/api/services',(req,res)=>{res.set('Cache-Control','no-store');res.json(services.list())});
router.post('/api/service-history/import',(req,res)=>{try{if(!['Owner','Company Admin'].includes(req.get('x-sv365-user-role')))return res.status(403).json({error:'Company administrator access required'});const rows=req.body?.rows;res.json(req.body?.commit===true?historyImport.commit(rows):{rows:historyImport.preview(rows)})}catch(e){res.status(400).json({error:e.message})}});
router.post('/service/:id/cancel',(req,res)=>{const r=services.get(req.params.id);if(!r)return res.status(404).send('Service booking not found');services.update(req.params.id,{status:'CANCELLED',cancelledAt:new Date().toISOString()});res.redirect('/service')});
router.post('/service/:id/reschedule',(req,res)=>{const r=services.get(req.params.id);if(!r)return res.status(404).send('Service booking not found');if(!req.body.requestedDate)return res.redirect('/service');try{services.update(req.params.id,{status:'SCHEDULED',requestedDate:requestedDateISO(req.body.requestedDate)});res.redirect('/service')}catch(e){res.status(400).send(page('service','Service Schedule',`<div class="panel" style="padding:24px"><h2>Unable to reschedule service</h2><p>${esc(e.message)}</p><a href="/service">Return to Service Schedule</a></div>`))}});
router.get('/service/:id/complete',(req,res)=>{const r=services.get(req.params.id);if(!r)return res.status(404).send('Service booking not found');res.send(page('service','Complete Service',`<style>.completeWrap{max-width:720px;margin:auto}.completeCard{background:#fff;border:1px solid #e3e8ef;border-radius:14px;overflow:hidden}.completeBody{padding:22px}.completeGrid{display:grid;grid-template-columns:1fr 1fr;gap:15px}.full{grid-column:1/-1}@media(max-width:700px){.completeGrid{grid-template-columns:1fr}.full{grid-column:auto}}</style><div class="completeWrap"><section class="title"><div><h1>Complete Service</h1><p>${esc(r.rego||r.assetId)} · ${esc(serviceConfig.label(r.serviceType))}</p></div><a class="secondary" href="/service">Back</a></section><form class="completeCard" method="post" action="/service/${encodeURIComponent(r.id)}/complete"><div class="completeBody">${r.defectId?`<p><b>Linked defect:</b> ${esc(r.defectId)} · ${esc(r.defectNotice?.defect||'')}<br><span class="sub">Completing this service clears the linked defect.</span></p>`:''}<div class="completeGrid"><div class="field"><label>Completed Date *</label><input name="completedDate" type="date" value="${today()}" required></div><div class="field"><label>Odometer / Hours</label><input name="completedReading" type="number" min="0"></div><div class="field full"><label>Completion Notes / Invoice Reference</label><textarea name="completionNotes"></textarea></div></div></div><div class="actions"><a class="secondary" href="/service">Cancel</a><button class="primary" type="submit">Mark Service Complete</button></div></form></div>`))});
router.post('/service/:id/complete',(req,res)=>{const r=services.get(req.params.id);if(!r)return res.status(404).send('Service booking not found');const completedReading=req.body.completedReading===''?null:Number(req.body.completedReading);services.update(req.params.id,{status:'COMPLETED',completedDate:req.body.completedDate||today(),completedReading:Number.isFinite(completedReading)?completedReading:null,completionNotes:String(req.body.completionNotes||'').trim()});const a=assets.find(x=>String(x.id)===String(r.assetId));if(a&&Number.isFinite(completedReading)&&completedReading!==null)a.reading=completedReading;res.redirect('/service-history?asset='+encodeURIComponent(r.assetId))});

