router.post('/api/service-parts/import',(req,res)=>{try{
 const b=req.body||{},asset=assets.find(a=>String(a.id)===String(b.assetId));if(!asset||!validListType(asset,b.serviceType))throw Error('Select a valid machine and service type.');
 const rows=require('../service-parts-csv').parse(b.csv),preview=parts.prepareImport(rows);
 if(b.commit===true){parts.importList(asset.id,b.serviceType,rows,b.revision);return res.json({saved:true,count:preview.length});}
 const data=parts.read(),existing=data.lists.find(x=>x.assetId===String(asset.id)&&x.serviceType===b.serviceType);
 res.json({assetName:asset.name||asset.rego||asset.id,plantId:asset.plantId||'',serviceType:b.serviceType,parts:preview,existingCount:existing?.items.length||0,revision:parts.listRevision(asset.id,b.serviceType,data)});
 }catch(e){res.status(400).json({error:e.message})}});
