router.post('/service/parts/catalog',(req,res)=>{try{parts.addPart(req.body||{});res.redirect('/service/parts?saved=1')}catch(e){partError(res,e)}});
router.post('/service/parts/catalog/:id',(req,res)=>{try{parts.updatePart(req.params.id,req.body||{});res.redirect('/service/parts?saved=1')}catch(e){partError(res,e)}});
router.post('/service/parts/list',(req,res)=>{try{const asset=assets.find(a=>String(a.id)===String(req.body.assetId));if(!asset||!validListType(asset,req.body.serviceType))throw new Error('Select a valid asset and service type');if(!['genuine','non-genuine'].includes(req.body.preference))throw new Error('Choose genuine or non-genuine parts first');const data=parts.read();for(const p of data.catalog.filter(p=>p.partKind===req.body.preference)){const quantity=Number(req.body['qty_'+p.id]||0);if(!Number.isInteger(quantity)||quantity<0||quantity>10)throw new Error('Part quantities must be whole numbers from 0 to 10.');}const items=data.catalog.filter(p=>p.partKind===req.body.preference&&Number(req.body['qty_'+p.id])>0).map(p=>({partId:p.id,quantity:req.body['qty_'+p.id]}));parts.saveList(asset.id,req.body.serviceType,items);for(const booking of services.list().filter(x=>String(x.assetId)===String(asset.id)&&x.serviceType===req.body.serviceType&&x.status==='SCHEDULED'&&x.partsRequired!==false&&!(x.parts||[]).length))services.update(booking.id,{parts:parts.snapshot(asset.id,req.body.serviceType),partsAllocationStatus:'pending confirmation',partsConfirmedAt:null});res.redirect('/service/parts?asset='+encodeURIComponent(asset.id)+'&type='+encodeURIComponent(req.body.serviceType)+'&preference='+encodeURIComponent(req.body.preference)+'#parts-builder')}catch(e){partError(res,e)}});
router.get('/service/:id/parts.pdf',(req,res)=>{const booking=services.get(req.params.id);if(!booking)return res.status(404).send('Service not found');const pdf=new PDFDocument({margin:45});res.type('application/pdf');res.set('Content-Disposition',`attachment; filename="service-parts-${String(booking.id).replace(/[^a-zA-Z0-9-]/g,'')}.pdf"`);pdf.pipe(res);pdf.fontSize(20).text('Service Parts Order List');pdf.moveDown(.5).fontSize(11).text(`Asset: ${booking.rego||booking.assetId} - ${booking.assetName||''}`).text(`Service: ${serviceConfig.label(booking.serviceType)}`).text(`Requested: ${displayRequestedDate(booking.requestedDate)}`).text(`Booking: ${booking.id}`);pdf.moveDown();let total=0,missingCosts=false;for(const line of booking.parts||[]){const cost=line.unitPrice==null?null:Number(line.quantity)*Number(line.unitPrice);if(cost==null)missingCosts=true;else total+=cost;pdf.fontSize(11).text(`${line.quantity} ${line.unit||'each'}  ${line.name}${line.sku?' ['+line.sku+']':''}${line.partKind?' · '+line.partKind:''}`,{continued:false});pdf.fontSize(9).fillColor('#475569').text(`Supplier: ${line.supplier||'—'}  |  ${money(line.unitPrice)} / ${line.unit||'each'}  |  ${money(cost)}  |  ${line.status||'pending approval'}`).fillColor('#000');pdf.moveDown(.5)}if(!(booking.parts||[]).length)pdf.text('No parts assigned to this service.');pdf.moveDown().fontSize(12).text(`Estimated parts total: ${money(total)}${missingCosts?' (incomplete - some costs not set)':''}`);pdf.end()});
router.get('/service/:id/parts',(req,res)=>{const r=services.get(req.params.id);if(!r)return res.status(404).send('Service not found');const rows=(r.parts||[]).map(line=>`<tr><td><b>${esc(line.name)}</b><div class="sub">${esc(line.sku||'No part number')} · ${esc(line.category)}</div></td><td>${esc(line.quantity)} ${esc(line.unit)}</td><td>${money(line.unitPrice)}</td><td>${esc(line.supplier||'—')}</td><td><form method="post" action="/service/${encodeURIComponent(r.id)}/parts/${encodeURIComponent(line.id)}/status"><select name="status" aria-label="Status for ${esc(line.name)}">${partsStatuses.map(x=>`<option value="${x}"${line.status===x?' selected':''}>${x}</option>`).join('')}</select><button class="mini">Save</button></form></td></tr>`).join('');res.send(page('service','Service Parts Order',`<style>${css}</style><div class="serviceWrap"><section class="title"><div><h1>Parts for ${esc(r.rego||r.assetId)}</h1><p>${esc(serviceConfig.label(r.serviceType))} · ${esc(displayRequestedDate(r.requestedDate))} · ${esc(r.id)}</p></div><div class="serviceActions"><a class="secondary" href="/service">Service Schedule</a><a class="primary" href="/service/${encodeURIComponent(r.id)}/parts.pdf">Download PDF</a></div></section><section class="panel"><div class="tablewrap"><table><thead><tr><th>Part</th><th>Quantity</th><th>Unit Price</th><th>Supplier</th><th>Order Status</th></tr></thead><tbody>${rows||'<tr><td colspan="5">No saved parts list was assigned when this service was scheduled.</td></tr>'}</tbody></table></div></section></div>`))});
router.post('/service/:id/parts/:partId/status',(req,res)=>{const r=services.get(req.params.id);if(!r)return res.status(404).send('Service not found');if(!partsStatuses.includes(req.body.status))return res.status(400).send('Invalid status');const lines=Array.isArray(r.parts)?r.parts.map(x=>({...x})):[],line=lines.find(x=>x.id===req.params.partId);if(!line)return res.status(404).send('Part not found');line.status=req.body.status;services.update(r.id,{parts:lines});res.redirect('/service/'+encodeURIComponent(r.id)+'/parts')});

