router.get('/service-history',(req,res)=>{
  const selected=String(req.query.asset||''),asset=assets.find(a=>String(a.id)===selected),options=assets.map(a=>`<option value="${esc(a.id)}"${String(a.id)===selected?' selected':''}>${esc(vehicleLabel(a))}</option>`).join('');
  const rows=selected?services.list().filter(r=>String(r.assetId)===selected).sort((a,b)=>new Date(b.completedDate||b.requestedDate)-new Date(a.completedDate||a.requestedDate)):[],completed=rows.filter(r=>r.status==='COMPLETED'),last=[...completed].sort((a,b)=>String(b.completedDate).localeCompare(String(a.completedDate)))[0];
  const table=rows.length?rows.map(r=>{const s=state(r);return `<tr><td>${esc(r.completedDate||'—')}</td><td>${esc(displayRequestedDate(r.requestedDate))}</td><td><b>${esc(serviceConfig.label(r.serviceType))}</b><div class="sub">${esc(r.id)}</div></td><td>${esc(r.serviceCentre||'—')}</td><td>${r.completedReading==null?'—':Number(r.completedReading).toLocaleString('en-AU')}</td><td><span class="pill ${s.cls}">${esc(s.label)}</span></td><td>${esc(r.completionNotes||r.notes||'—')}</td></tr>`}).join(''):'<tr><td colspan="7"><div class="empty">No service records for this asset.</div></td></tr>';
  res.send(page('service-history','Service History',`<style>${css}</style><div class="serviceWrap"><section class="title"><div><h1>Service History</h1><p>Select an asset to view its complete service record.</p></div><div class="serviceActions"><a class="secondary" href="/service">Service Schedule</a><a class="secondary" href="/service-history/import">Import History</a></div></section><form class="filterRow" method="get" action="/service-history"><div class="field"><label>Asset</label><select name="asset" required><option value="">Select Asset</option>${options}</select></div><button class="primary" type="submit">Load History</button></form>${asset?`<div class="historyHero"><h2>${esc(asset.rego||asset.id)} — ${esc(asset.name)}</h2><div class="sub">${esc(asset.type)} · Current reading ${Number(asset.reading||0).toLocaleString('en-AU')}</div><div style="margin-top:10px"><b>${completed.length}</b> completed service(s)${last?' · Last service '+esc(last.completedDate)+' · '+esc(last.serviceType):''}</div></div><section class="panel"><div class="tablewrap"><table><thead><tr><th>Completed</th><th>Requested</th><th>Service</th><th>Centre</th><th>Reading</th><th>Status</th><th>Notes</th></tr></thead><tbody>${table}</tbody></table></div></section>`:'<div class="empty">Select an asset to view service history.</div>'}</div>`));
});

router.get('/service-history/import',(req,res)=>{
 if(!['Owner','Company Admin'].includes(req.get('x-sv365-user-role')))return res.status(403).send('Company administrator access required');
 res.send(page('service-history','Import Service History',String.raw`<style>${css}</style><div class="serviceWrap"><section class="title"><div><h1>Import Last Service Records</h1><p>Match Fleet ID to Plant ID in this company. One historical baseline per asset.</p></div><a class="secondary" href="/service-history">Service History</a></section><section class="panel" style="padding:20px"><p>Paste three columns from Excel: <b>FLEET ID, LAST SERVICES, CURRENT HRS/KMS</b>. Dates may be DD/MM/YYYY or YYYY-MM-DD. Service type and work details remain unrecorded.</p><textarea id="historyData" style="width:100%;min-height:180px" placeholder="FLEET ID\tLAST SERVICES\tCURRENT HRS/KMS"></textarea><div class="serviceActions" style="margin:15px 0"><button class="secondary" id="historyPreview">Preview matches</button><button class="primary" id="historyCommit" disabled>Import matched records</button></div><div id="historyResult" role="status"></div></section></div><script>(function(){const input=document.getElementById('historyData'),out=document.getElementById('historyResult'),commit=document.getElementById('historyCommit');let rows=[];function parse(){const lines=input.value.trim().split(/\r?\n/).filter(Boolean);if(!lines.length)throw Error('Paste service rows first');const sep=lines[0].includes('\t')?'\t':',';const cells=line=>{if(sep==='\t')return line.split('\t');let result=[],part='',quoted=false;for(let i=0;i<line.length;i++){const c=line[i];if(c==='"'&&line[i+1]==='"'&&quoted){part+='"';i++}else if(c==='"')quoted=!quoted;else if(c===','&&!quoted){result.push(part);part=''}else part+=c}result.push(part);return result};if(/^\s*FLEET ID/i.test(lines[0]))lines.shift();return lines.map(line=>{const [fleetId,rawDate,reading]=cells(line).map(x=>x.trim());let date=rawDate||'';const m=date.match(/^(\d{1,2})[./-](\d{1,2})[./-](\d{4})$/);if(m)date=m[3]+'-'+m[2].padStart(2,'0')+'-'+m[1].padStart(2,'0');return{fleetId,date,reading:reading?.replace(/,/g,'')}})}async function request(save){try{if(!save)rows=parse();const response=await fetch('/api/service-history/import',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({rows,commit:save})}),data=await response.json();if(!response.ok)throw Error(data.error||'Import failed');if(save){out.textContent=data.imported+' records imported; '+data.alreadyImported+' already present.';commit.disabled=true;return}const result=data.rows;commit.disabled=!result.length||result.some(x=>!['Ready','Already imported'].includes(x.status));out.innerHTML='<p>'+result.filter(x=>x.status==='Ready').length+' ready · '+result.filter(x=>x.status==='Already imported').length+' already imported · '+result.filter(x=>!['Ready','Already imported'].includes(x.status)).length+' need attention</p><div class="tablewrap"><table><thead><tr><th>Fleet ID</th><th>Date</th><th>Reading</th><th>Matched asset</th><th>Status</th></tr></thead><tbody>'+result.map(x=>'<tr><td>'+escapeHtml(x.fleetId)+'</td><td>'+escapeHtml(x.date)+'</td><td>'+escapeHtml(x.reading)+'</td><td>'+escapeHtml(x.assetName||'—')+'</td><td>'+escapeHtml(x.status)+'</td></tr>').join('')+'</tbody></table></div>'}catch(e){commit.disabled=true;out.textContent=e.message}}function escapeHtml(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}input.addEventListener('input',()=>{commit.disabled=true});document.getElementById('historyPreview').onclick=()=>request(false);commit.onclick=()=>request(true)})();</script>`));
});

module.exports=router;
